import {Component} from '@angular/core';
import {Router, RouterModule} from '@angular/router'; // Import RouterModule and Router
import {FormsModule} from '@angular/forms'; // Import FormsModule
import {NgIf, NgFor} from '@angular/common'; // Import NgIf, NgFor
import {ProductService} from '../product.service';
import {Product} from '../models/product.model';

@Component({
    selector: 'app-header',
    standalone: true, // Make standalone
    imports: [RouterModule, FormsModule, NgIf, NgFor], // Add FormsModule, NgIf, NgFor
    templateUrl: './header.component.html',
    styleUrls: ['./header.component.css']
})
export class HeaderComponent {
    searchTerm: string = '';
    searchResults: Product[] = [];
    isDropdownVisible: boolean = false;
    isLoading: boolean = false;
    // Debounce timer
    private searchDebounceTimer: any;

    constructor(private router: Router, private productService: ProductService) {}

    // Called on input event to update searchTerm and potentially trigger live search (debounced)
    onSearchInput(): void {
        if (!this.searchTerm.trim()) {
            this.searchResults = [];
            this.isDropdownVisible = false;
            clearTimeout(this.searchDebounceTimer); // Clear any pending search
            return;
        }
        // Optional: Debounce live search if desired
        // clearTimeout(this.searchDebounceTimer);
        // this.searchDebounceTimer = setTimeout(() => {
        //     this.fetchSearchResults(this.searchTerm);
        // }, 300); // Adjust debounce time as needed
    }

    // Called on blur event from the search input
    onSearchBlur(): void {
        // Only search if there's a term, otherwise input event would have cleared
        if (this.searchTerm.trim()) {
            this.fetchSearchResults(this.searchTerm.trim());
        }
        // Delay hiding dropdown to allow click on results
        setTimeout(() => {
            // Check if the focus is now on a dropdown item or related element
            // This simple timeout might not be robust enough for all cases.
            // A more robust solution involves checking activeElement or using focusout with relatedTarget.
            if (!document.activeElement?.closest('.search-results-dropdown-item')) {
                 this.isDropdownVisible = false;
            }
        }, 200);
    }

    // Called on focus event of the search input
    onSearchFocus(): void {
        if (this.searchTerm.trim() && this.searchResults.length > 0) {
            this.isDropdownVisible = true;
        } else if (this.searchTerm.trim()) {
            // If there's a term but no results shown, maybe fetch again or just show empty
            // For now, let blur handle fetching.
        }
    }

    fetchSearchResults(term: string): void {
        if (!term) {
            this.searchResults = [];
            this.isDropdownVisible = false;
            this.isLoading = false;
            return;
        }
        this.isLoading = true;
        this.isDropdownVisible = true; // Show dropdown as soon as search starts
        this.productService.searchProducts(term, 0, 5, 'ASC', 'name').subscribe({
            next: (response) => {
                this.searchResults = response.content;
                this.isLoading = false;
            },
            error: () => {
                this.searchResults = [];
                this.isLoading = false;
                // console.error('Error fetching search results:', error);
            }
        });
    }

    // Navigate to the full search results page (typically on Enter)
    navigateToSearchResultsPage(): void {
        if (this.searchTerm.trim()) {
            this.router.navigate(['/products'], { queryParams: { search: this.searchTerm.trim() } });
            this.clearSearchState();
        }
    }

    // Navigate to a specific product's detail page
    navigateToProduct(productId: string | undefined): void {
        if (productId) {
            this.router.navigate(['/product-detail', productId]);
            this.clearSearchState();
        }
    }

    clearSearchState(): void {
        this.searchTerm = '';
        this.searchResults = [];
        this.isDropdownVisible = false;
        this.isLoading = false;
        clearTimeout(this.searchDebounceTimer);
    }

    // Prevent blur from hiding dropdown immediately if a result is clicked
    onResultMouseDown(productId: string | undefined): void {
        this.navigateToProduct(productId);
    }
}
<header class="sticky top-0 z-50 bg-white shadow-md">
    <div class="container mx-auto px-4">
        <div class="flex h-16 items-center justify-between">
            <a class="flex items-center gap-2" routerLink="/">
                <img alt="Company Logo" class="h-8 w-auto" src="assets/logo.svg"/>
                <span class="text-xl font-semibold text-[#1b120e]">ElectroMart</span>
            </a>
            <nav class="hidden items-center gap-6 md:flex">
                <a class="text-sm font-medium text-[#7f5e53] hover:text-[#1b120e] transition-colors" routerLink="/">Home</a>
                <a class="text-sm font-medium text-[#7f5e53] hover:text-[#1b120e] transition-colors" routerLink="/products">Products</a>
                <a class="text-sm font-medium text-[#7f5e53] hover:text-[#1b120e] transition-colors" routerLink="/about">About Us</a>
                <a class="text-sm font-medium text-[#7f5e53] hover:text-[#1b120e] transition-colors" routerLink="/contact">Contact</a>
            </nav>
            <div class="flex items-center gap-4">
                <div class="flex-1 max-w-xs">
                    <!-- Make this label relative for dropdown positioning -->
                    <label class="flex w-full items-stretch rounded-lg h-10 relative">
                        <div class="text-slate-500 flex border border-slate-300 bg-slate-50 items-center justify-center pl-3 rounded-l-lg border-r-0"
                             data-icon="MagnifyingGlass" data-size="20px" data-weight="regular">
                            <svg fill="currentColor" height="20px" viewBox="0 0 256 256" width="20px"
                                 xmlns="http://www.w3.org/2000/svg">
                                <path d="M229.66,218.34l-50.07-50.06a88.11,88.11,0,1,0-11.31,11.31l50.06,50.07a8,8,0,0,0,11.32-11.32ZM40,112a72,72,0,1,1,72,72A72.08,72.08,0,0,1,40,112Z"></path>
                            </svg>
                        </div>
                        <input class="form-input flex w-full min-w-0 flex-1 resize-none overflow-hidden rounded-r-lg text-[#141414] focus:outline-none focus:ring-2 focus:ring-[#141414] focus:border-transparent border border-slate-300 bg-slate-50 h-full placeholder:text-slate-500 px-3 text-sm font-normal leading-normal border-l-0"
                               placeholder="Search products..."
                               [(ngModel)]="searchTerm"
                               (input)="onSearchInput()"
                               (blur)="onSearchBlur()"
                               (focus)="onSearchFocus()"
                               (keyup.enter)="navigateToSearchResultsPage()" />

                        <!-- Dropdown for search results -->
                        <div *ngIf="isDropdownVisible"
                             class="absolute top-full left-0 right-0 mt-1 bg-white border border-gray-300 rounded-md shadow-lg z-[100]">
                            <div *ngIf="isLoading" class="p-3 text-center text-gray-500">Loading...</div>
                            <ul *ngIf="!isLoading && searchResults.length > 0" class="max-h-60 overflow-y-auto">
                                <li *ngFor="let product of searchResults"
                                    (mousedown)="onResultMouseDown(product.id)"
                                    class="px-4 py-2 hover:bg-gray-100 cursor-pointer search-results-dropdown-item">
                                    {{ product.name }}
                                </li>
                            </ul>
                            <div *ngIf="!isLoading && searchResults.length === 0 && searchTerm.trim().length > 0"
                                 class="p-3 text-center text-gray-500">
                                No products found for "{{ searchTerm }}".
                            </div>
                        </div>
                    </label>
                </div>
